    Bug 1987238 - Attach ComposeCommandController to the editor, not to the chrome window. r=edicharry


    The original implementation also attached to the editor element. See
    https://phabricator.services.mozilla.com/D263970

    Differential Revision: https://phabricator.services.mozilla.com/D264094

diff --git a/mail/components/compose/content/ComposerCommands.js b/mail/components/compose/content/ComposerCommands.js
index 5f819dbc779..33cb81fab76 100644
--- a/mail/components/compose/content/ComposerCommands.js
+++ b/mail/components/compose/content/ComposerCommands.js
@@ -154,45 +154,53 @@ function SetupTextEditorCommands() {
  *   register the manually created commands.
  */
 function GetComposerCommandTable() {
-  if (gComposerCommandController) {
-    return gComposerCommandController;
+  const editorWindow = GetCurrentEditorElement()?.contentWindow;
+  if (!editorWindow) {
+    return null;
+  }
+
+  if (!gComposerCommandController) {
+    gComposerCommandController = {
+      _commands: {},
+      registerCommand(cmd, command) {
+        this._commands[cmd] = command;
+      },
+      supportsCommand(cmd) {
+        return cmd in this._commands;
+      },
+      isCommandEnabled(cmd) {
+        return (
+          this._commands[cmd]?.isCommandEnabled(
+            cmd,
+            GetCurrentEditorElement()
+          ) || false
+        );
+      },
+      doCommand(cmd) {
+        return this._commands[cmd].doCommand(cmd, GetCurrentEditorElement());
+      },
+      getCommandStateWithParams() {
+        throw Components.Exception(
+          "Not implemented",
+          Cr.NS_ERROR_NOT_IMPLEMENTED
+        );
+      },
+      doCommandWithParams() {
+        throw Components.Exception(
+          "Not implemented",
+          Cr.NS_ERROR_NOT_IMPLEMENTED
+        );
+      },
+      QueryInterface: ChromeUtils.generateQI([
+        "nsIController",
+        "nsICommandController",
+      ]),
+    };
+    // IMPORTANT: attach to the editor document, not the chrome window, so commands
+    // enable/disable with focus.
+    editorWindow.controllers.insertControllerAt(0, gComposerCommandController);
   }

